cards.content:
{% set st = states.binary_sensor | selectattr('entity_id','search','^binary_sensor\\.helium_containers_.*_state$') | list %}{% set up = st | selectattr('state','eq','on') | list %}{% set bad = st | rejectattr('state','eq','on') | list %}# helium<span>{{ up | count }}/{{ st | count }} services up</span>

**MEDIA STACK** &nbsp; 🧠 {{ states('sensor.helium_cpu_usage') }}% &nbsp; 🧮 {{ states('sensor.helium_memory_usage') }}% &nbsp; ⏱ up {{ relative_time(as_datetime(states('sensor.helium_last_boot'))) }}

{% if bad %}**⚠ NOT RUNNING** &nbsp; {{ bad | map(attribute='name') | map('replace','helium Containers ','') | map('replace',' State','') | join(' · ') }}{% else %}**ALL SERVICES RUNNING**{% endif %}

card_mod.style:
ha-card {
  padding: 24px 28px;
  background: radial-gradient(ellipse at top right, rgba(110,171,174,0.18), transparent 60%), var(--card-background-color);
  border-radius: 22px;
}
ha-card h1 { font-size: 64px; font-weight: 800; letter-spacing: -0.04em; line-height: 1; margin: 0 0 14px 0; font-variant-numeric: tabular-nums; }
ha-card h1 span { font-size: 22px; font-weight: 400; color: var(--secondary-text-color); letter-spacing: 0; vertical-align: top; margin-left: 4px; }
ha-card p { color: var(--secondary-text-color); font-size: 13px; margin: 0 0 6px 0; line-height: 1.6; }
ha-card p:last-child { margin-bottom: 0; }
ha-card p strong:first-child { color: var(--secondary-text-color); letter-spacing: 0.16em; font-weight: 800; margin-right: 8px; }

